'@
    'data/os-lifecycle.json' = @'
{
  "schemaVersion": "1.0",
  "snapshotDate": "2026-09-23",
  "notes": "Dates verified against official vendor pages on 2026-09-23. Windows: Microsoft pages show end times as 'M/D/YYYY 6:59:59 AM' PT of the day after the last Patch Tuesday; stored value is the last supported day (the Patch Tuesday, i.e. page date minus one day). Windows endOfSupport = Extended End Date. RHEL endOfMainstream = end of Full Support, endOfSupport = end of Maintenance Support (ELS excluded). Ubuntu and Proxmox pages give month precision only; stored as last day of month and flagged datePrecision=month. Debian endOfSupport = end of regular Debian security support, endOfLts = end of Debian LTS (ELTS excluded). null means not confirmed on an official page. Azure Stack HCI / Azure Local omitted (Modern Lifecycle, per-version servicing; build mapping unclear). Treat a date as 'supported through end of that day'.",
  "matching": {
    "windows-server": {
      "source": "Win32_OperatingSystem.BuildNumber",
      "rule": "exact string match of BuildNumber to branch (e.g. '17763'). Also require ProductType != 1 (server) to avoid matching client Windows builds that share a number (e.g. 26100 is also Windows 11 24H2, 14393 is also Windows 10 1607, 17763 is Windows 10 1809)."
    },
    "linux": {
      "source": "/etc/os-release",
      "productFromId": {
        "rhel": "rhel",
        "rocky": "rocky",
        "almalinux": "almalinux",
        "ubuntu": "ubuntu",
        "debian": "debian"
      },
      "rule": "rhel/rocky/almalinux/debian: branch = VERSION_ID split on '.' take first part ('9.4' -> '9', '12' -> '12'). ubuntu: branch = full VERSION_ID ('22.04'). Only Ubuntu LTS releases are listed; non-LTS VERSION_IDs have no entry."
    },
    "proxmox-ve": {
      "source": "pveversion output (pve-manager/X.Y.Z)",
      "rule": "branch = major version X. /etc/os-release reports the Debian base (ID=debian), so check Proxmox first."
    }
  },
