    try { if (theme === 'system') window.localStorage.removeItem(THEME_KEY); else window.localStorage.setItem(THEME_KEY, theme); } catch (e) { /* storage unavailable */ }
    applyTheme(theme);
    onThemeChange();
  });
  if (window.matchMedia) {
