      detail.appendChild(h('div', { class: 'card-head' }, h('h2', null, 'If ' + assetName(x.component) + ' fails'), h('span', { class: 'state state-' + (red === 'redundant' ? 'ok' : red === 'none' ? 'bad' : 'warn') }, 'Redundancy: ' + (red || 'unknown'))));
