        { key: 'comp', label: 'Compensating control', sort: function (x) { return str(x.compensatingControl); }, render: function (x) { return h('span', { class: 'break small' }, str(x.compensatingControl)); } },
        { key: 'ticket', label: 'Ticket', sort: function (x) { return str(x.ticket); }, render: function (x) { return h('span', { class: 'mono small' }, str(x.ticket)); } },
        { key: 'expires', label: 'Expires', sort: function (x) { return str(x.expires); }, render: function (x) { return h('span', { class: 'nowrap' }, str(x.expires) || '-'); } },
        { key: 'findings', label: 'Findings', num: true, sort: function (x) { return num(x.findings); }, render: function (x) { return fmtN(x.findings); } },
        { key: 'flags', label: 'Flags', sort: function (x) { return arr(x.flags).join(','); }, render: function (x) { return h('span', { class: 'small muted' }, arr(x.flags).join(', ')); } }
      ]
    });
    ext.setRows(excs);
    el.appendChild(h('div', { class: 'card section' }, h('h2', null, 'Sign-offs (' + fmtN(signoffs.length) + ')'), sgt.el));
    el.appendChild(h('div', { class: 'card section' }, h('h2', null, 'Exceptions (' + fmtN(excs.length) + ')'), ext.el));
    el.appendChild(h('div', { class: 'card section ai-hint' }, h('h2', null, 'Record sign-offs and exceptions'),
      h('p', { class: 'small' }, 'Manual checks are signed off, and failing checks excepted, in the scope file; replay the package with it and -AuditPack to write the audit-pack folder. An exception without an approver never counts as excepted.'),
      h('pre', { class: 'mono small' }, '"signoffs": [\n  { "ruleId": "VC-SSO-POLICY", "asset": "name:vc01*", "reviewer": "auditor", "decision": "satisfied", "evidenceRef": "EVD-12", "dateUtc": "2026-10-01" }\n],\n"exceptions": [\n  { "ruleId": "ESXI-SVC-SSH", "asset": "esx03*", "owner": "infra", "approver": "CISO", "compensatingControl": "jump host only", "ticket": "CHG-7", "expires": "2027-01-31", "rationale": "vendor support" }\n]')));
  };

  renderers.exports = function (el) {
    const base = 'vsat-' + safeFilePart(run.id);
    el.appendChild(pageHead('h-exports', 'Exports', 'All exports are generated locally in your browser. Nothing is uploaded.'));
    el.appendChild(h('div', { class: 'notice notice-warn' }, h('strong', null, 'Handle exports as sensitive'), 'Exports contain infrastructure names, addresses and security weaknesses. Store and share them under your organization’s data-classification rules.'));
    function card(title, desc, actions) { return h('div', { class: 'card' }, h('h2', null, title), h('p', null, desc), h('div', { class: 'actions' }, actions)); }
    el.appendChild(h('div', { class: 'export-grid' },
      card('Results JSON', 'The complete results.json embedded in this report (findings, assets, relationships, analysis).', [btn('Download JSON', function () { download(base + '-results.json', new Blob([JSON.stringify(D, null, 2)], { type: 'application/json' })); }, 'btn-primary')]),
      card('Findings CSV', 'One row per finding. Cells beginning with = + - @ are prefixed with a quote to prevent spreadsheet formula execution.', [
        btn('All findings', function () { download(base + '-findings.csv', new Blob([findingsCsv(findings)], { type: 'text/csv;charset=utf-8' })); }, 'btn-primary'),
        btn('FAIL / UNKNOWN / ERROR', function () { download(base + '-findings-open.csv', new Blob([findingsCsv(findings.filter(function (f) { return f.result === 'FAIL' || f.result === 'UNKNOWN' || f.result === 'ERROR'; }))], { type: 'text/csv;charset=utf-8' })); })]),
      hasChanges ? card('Engagement timeline CSV', 'One row per platform change in the engagement window, with the checks it touches.', [btn('Download timeline', function () { download(base + '-changes.csv', new Blob([changesCsv()], { type: 'text/csv;charset=utf-8' })); }, 'btn-primary')]) : null,
      card('Worklist CSV', 'Work packages expanded to one row per linked finding, for ticketing and change planning.', [btn('Download worklist', function () { download(base + '-worklist.csv', new Blob([worklistCsv()], { type: 'text/csv;charset=utf-8' })); }, 'btn-primary')]),
      card('Topology image', 'Current topology view with legend and scope label (run ID and time). Expand the graph first to include more detail.', [btn('SVG', exportSvg, 'btn-primary'), btn('PNG', exportPng)]),
      card('Print / PDF', 'Prints all sections with navigation hidden. Use your browser’s "Save as PDF" for a PDF copy.', [btn('Print report', function () { PAGES.forEach(ensureRendered); window.print(); })])));
  };

  // =====================================================================
  // Blast radius (view code: assets/report/blast-view.js, concatenated before this file)
  // =====================================================================
  renderers.blast = function (el) {
    const root = el.querySelector('[data-br="root"]');
    if (!root) return;
    VsatBlastView.mount(root, D, {
      zoneOf: function (id) { const a = assetById.get(str(id)); return a ? str(a.zone) : ''; },
      nameOf: assetName
    });
  };

  // =====================================================================
  // Boot
  // =====================================================================
  route();
})();
'@
    'assets/ui/app.html' = @'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="__VSAT_CSP__">
<meta name="referrer" content="no-referrer">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light dark">
<meta name="robots" content="noindex, nofollow">
<title>__VSAT_TITLE__</title>
<style>__VSAT_CSS__</style>
</head>
<body>
<a class="skip-link" href="#main">Skip to content</a>
<header class="app-header">
  <div class="brand">
    <svg class="brand-mark" viewBox="0 0 24 28" width="24" height="28" aria-hidden="true" focusable="false">
      <path d="M12 1 L22 5 V13 C22 20 17.5 24.8 12 27 C6.5 24.8 2 20 2 13 V5 Z" fill="currentColor"/>
      <path d="M7.5 13.5 L10.8 16.8 L16.8 10.2" fill="none" stroke="#ffffff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
    <span class="wordmark">VSAT</span>
    <span class="brand-sub">Guided assessment</span>
  </div>
  <div class="header-meta">
    <span id="hdr-version" class="hdr-item">-</span>
    <span id="hdr-mode" class="mode-badge" hidden>DEMO MODE</span>
    <span class="hdr-item local-note" title="Local session bound to 127.0.0.1. VSAT only reads from the systems it audits.">127.0.0.1 &middot; read-only</span>
  </div>
</header>
<div class="layout">
  <nav class="stepper" aria-label="Assessment steps">
    <ol id="steps"></ol>
  </nav>
  <main id="main" tabindex="-1">
    <div id="alert" class="notice notice-bad" role="alert" hidden></div>
    <div id="view"></div>
  </main>
</div>
<template id="blast-template">
  <div class="br" data-br="root">
    <div class="br-top" data-br="top">
      <div class="br-ask">
        <label for="entry">If this is compromised</label>
        <select id="entry" class="br-entry" data-br="entry"></select>
        <p class="br-verdict" data-br="verdict" aria-live="polite"></p>
        <p class="br-sub" data-br="sub"></p>
        <p class="br-scope" data-br="scope"></p>
      </div>
      <div class="br-switch" role="group" aria-label="View">
        <button type="button" data-br-view="map" aria-pressed="true">Map</button>
        <button type="button" data-br-view="list" aria-pressed="false">List</button>
      </div>
    </div>
    <p class="br-partial" data-br="partial" role="note" hidden></p>
    <div class="br-empty-state" data-br="empty" hidden></div>
    <div class="br-main" data-br="main">
      <div class="br-panel">
        <div class="br-canvas-wrap">
          <div class="br-canvas" data-br="canvas">
            <svg data-br="svg" viewBox="-130 -10 1160 920" role="img" aria-labelledby="br-svg-title"><title id="br-svg-title">Blast radius map</title></svg>
            <div class="br-tip" data-br="tip" role="tooltip"></div>
          </div>
          <p class="br-mapnote" data-br="mapnote" hidden></p>
          <div class="br-legend" role="group" aria-label="Legend">
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><circle cx="14" cy="7" r="5.5" fill="none" stroke="currentColor" stroke-width="1.75"/></svg>Account</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><rect x="8" y="1" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.75"/></svg>Host</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><rect x="9" y="2" width="10" height="10" rx="3" fill="none" stroke="currentColor" stroke-width="1.75"/></svg>VM</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><path d="M14 0 L21 7 L14 14 L7 7 Z" fill="none" stroke="currentColor" stroke-width="2"/></svg>Crown jewel</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><line x1="1" y1="7" x2="27" y2="7" stroke="currentColor" stroke-width="2"/></svg>Seen in config</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><line x1="1" y1="7" x2="27" y2="7" stroke="currentColor" stroke-width="2" stroke-dasharray="7 5"/></svg>Inferred from policy</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><line x1="1" y1="7" x2="27" y2="7" stroke="currentColor" stroke-width="2.5" stroke-dasharray="1.5 4.5" stroke-linecap="round"/></svg>Matched by IP</span>
            <span><svg viewBox="0 0 28 14" aria-hidden="true" focusable="false"><line x1="1" y1="7" x2="27" y2="7" stroke="currentColor" stroke-width="2" stroke-dasharray="9 4 2 4"/></svg>Declared by you</span>
            <span>Rings numbered by steps from the compromised point · shaded area = current reach · red = attacker reach · blue = your fix</span>
          </div>
        </div>
        <div class="br-list" data-br="list"></div>
      </div>
      <aside class="br-panel br-fix" aria-labelledby="br-fix-h">
        <h2 id="br-fix-h">Break the most paths</h2>
        <p class="br-hint">Ranked by how many attack paths each fix closes right now, across every starting point. Tick one to see what is left.</p>
        <p class="br-hint" data-br="fixnote" hidden></p>
        <div class="br-meter" aria-hidden="true"><i data-br="meter"></i></div>
        <div class="br-meter-lbl"><span data-br="meter-a"></span><span data-br="meter-b"></span></div>
        <div data-br="fixes"></div>
        <p class="br-reroute" data-br="reroute" role="status"></p>
        <button type="button" class="br-reset" data-br="reset" hidden>Clear selected fixes</button>
      </aside>
    </div>
    <section class="br-panel br-path" aria-labelledby="br-path-h" data-br="path-wrap">
      <h2 id="br-path-h">How the attacker gets there</h2>
      <div class="br-pick" data-br="pick" role="group" aria-label="Crown jewel"></div>
      <p class="br-conf" data-br="conf"></p>
      <ol class="br-steps" data-br="steps"></ol>
    </section>
    <section class="br-panel br-gaps" aria-labelledby="br-gaps-h" data-br="gaps-wrap" hidden>
      <h2 id="br-gaps-h">Collect this to confirm</h2>
      <p class="br-hint">Routes that need one hop VSAT could not verify. They are never counted as attack paths or ranked; collect the named evidence to confirm or rule them out.</p>
      <ul data-br="gaps"></ul>
    </section>
  </div>
</template>
<div id="live" class="sr-only" aria-live="polite"></div>
<script>__VSAT_JS__</script>
</body>
</html>
'@
    'assets/ui/app.css' = @'
/* VSAT 2.0 local guided UI — no external resources; inlined by the engine under a hash-based CSP. */
:root {
  --bg: #f4f6f9; --surface: #ffffff; --surface-2: #f0f3f7; --surface-3: #e6ebf1; --border: #d5dce4; --border-strong: #b6c0cb;
  --text: #16202a; --text-2: #4a5663; --accent: #1d5bbf; --accent-contrast: #ffffff; --accent-soft: #e5eefb; --focus: #1d5bbf;
  --header-bg: #0f1b2b; --header-text: #e8eef5; --header-text-2: #a9b7c6; --brand: #4c8dff;
  --shadow: 0 1px 2px rgba(16,24,40,.06), 0 1px 3px rgba(16,24,40,.08);
  --ok: #1a7431; --ok-bg: #e6f4ea; --warn: #8a5a00; --warn-bg: #fff4d6; --warn-border: #e5b53c; --bad: #a4161a; --bad-bg: #fde8e8; --bad-border: #e5898b;
  --sev-critical: #a4161a; --sev-high: #b93d0a; --sev-medium: #8f5600; --sev-low: #0b6a80; --sev-info: #56616d;
  --radius: 8px; --radius-sm: 5px;
  --font: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0d1117; --surface: #151b23; --surface-2: #1b232d; --surface-3: #242e3a; --border: #2c3744; --border-strong: #3d4a59;
    --text: #e6edf3; --text-2: #aeb9c5; --accent: #6ea8fe; --accent-contrast: #0d1117; --accent-soft: #1b2b44; --focus: #8bb9ff;
    --header-bg: #0a0f15; --header-text: #e6edf3; --header-text-2: #9aa7b5; --brand: #6ea8fe; --shadow: 0 1px 2px rgba(0,0,0,.4);
    --ok: #56d47a; --ok-bg: #11301b; --warn: #f0c35a; --warn-bg: #33280f; --warn-border: #7a5d18; --bad: #ff8a8a; --bad-bg: #3a1618; --bad-border: #7c2a2d;
    --sev-critical: #ff7b7b; --sev-high: #ff9a5c; --sev-medium: #e8b54a; --sev-low: #4fc3d9; --sev-info: #a3aebb;
    color-scheme: dark;
  }
}
*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.5 var(--font); }
h1, h2, h3 { line-height: 1.25; margin: 0 0 .5em; }
h1 { font-size: 1.4rem; font-weight: 650; }
h2 { font-size: 1.08rem; font-weight: 650; }
h3 { font-size: .95rem; font-weight: 650; }
p { margin: 0 0 .6em; }
ul, ol { margin: 0 0 .6em; padding-left: 1.3em; }
[hidden] { display: none !important; }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.sr-only { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip-link { position: absolute; left: 8px; top: -40px; background: var(--accent); color: var(--accent-contrast); padding: 6px 12px; border-radius: var(--radius-sm); z-index: 10; }
.skip-link:focus { top: 8px; }
.muted { color: var(--text-2); }
.small { font-size: .86em; }
.mono { font-family: var(--mono); font-size: .92em; overflow-wrap: anywhere; }
.break { overflow-wrap: anywhere; }

.app-header { display: flex; align-items: center; gap: 20px; flex-wrap: nowrap; min-height: 48px; padding: 6px 24px; background: var(--header-bg); color: var(--header-text); white-space: nowrap; }
.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark { color: var(--brand); }
.wordmark { font-weight: 800; font-size: 1.2rem; letter-spacing: .08em; }
.brand-sub { color: var(--header-text-2); font-size: .85rem; padding-left: 10px; border-left: 1px solid rgba(255,255,255,.18); }
.header-meta { margin-left: auto; display: flex; gap: 14px; align-items: center; flex-wrap: nowrap; min-width: 0; overflow: hidden; font-size: .82rem; color: var(--header-text-2); }
.header-meta .local-note { overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 900px) { .brand-sub, .header-meta .local-note { display: none; } }
.mode-badge { background: #3b2a06; color: #ffd98a; border: 1px solid #7a5a12; border-radius: 999px; padding: 2px 10px; font-weight: 700; font-size: .75rem; letter-spacing: .05em; }

.layout { display: grid; grid-template-columns: 260px minmax(0, 1fr); gap: 24px; max-width: 1200px; margin: 0 auto; padding: 24px; }
.stepper ol { list-style: none; margin: 0; padding: 0; position: sticky; top: 16px; }
.stepper li { margin: 0 0 4px; }
.stepper button { all: unset; box-sizing: border-box; display: flex; align-items: center; gap: 10px; width: 100%; padding: 9px 10px; border-radius: var(--radius-sm); cursor: pointer; color: var(--text); font-weight: 600; }
.stepper button:hover:not([disabled]) { background: var(--surface-2); }
.stepper button:focus-visible { outline: 2px solid var(--focus); }
.stepper button[disabled] { cursor: not-allowed; color: var(--text-2); opacity: .7; }
.stepper button[aria-current="step"] { background: var(--accent-soft); color: var(--accent); }
.stepper .num { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; background: var(--surface-3); font-size: .8rem; font-weight: 700; flex: none; }
.stepper .done .num { background: var(--ok); color: #fff; }
.stepper button[aria-current="step"] .num { background: var(--accent); color: var(--accent-contrast); }
.stepper .req { font-size: .66rem; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: var(--warn); border: 1px solid var(--warn-border); border-radius: 3px; padding: 0 4px; margin-left: auto; }

main:focus { outline: none; }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px 20px; box-shadow: var(--shadow); margin-bottom: 16px; }
.step-head p { color: var(--text-2); }
.notice { border: 1px solid var(--border); border-left-width: 4px; border-radius: var(--radius-sm); padding: 10px 14px; background: var(--surface); margin: 0 0 14px; }
.notice strong { display: block; margin-bottom: 2px; }
.notice-warn { border-color: var(--warn-border); border-left-color: var(--warn); background: var(--warn-bg); }
.notice-bad { border-color: var(--bad-border); border-left-color: var(--bad); background: var(--bad-bg); }
.notice-ok { border-color: var(--ok); background: var(--ok-bg); }
.notice-info { border-left-color: var(--accent); background: var(--accent-soft); }
.state { font-weight: 700; font-size: .72rem; letter-spacing: .05em; padding: 2px 8px; border-radius: var(--radius-sm); border: 1px solid; white-space: nowrap; text-transform: uppercase; }
.state-ok { color: var(--ok); background: var(--ok-bg); border-color: var(--ok); }
.state-warn { color: var(--warn); background: var(--warn-bg); border-color: var(--warn-border); }
.state-bad { color: var(--bad); background: var(--bad-bg); border-color: var(--bad-border); }
.state-neutral { color: var(--text-2); background: var(--surface-2); border-color: var(--border-strong); }
.checks { list-style: none; padding: 0; margin: 0; }
.checks li { display: grid; grid-template-columns: 90px 1fr; gap: 10px; padding: 9px 0; border-bottom: 1px solid var(--border); align-items: start; }
.checks li:last-child { border-bottom: 0; }
.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.spacer { flex: 1; }
.actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 14px; align-items: center; }
.btn { display: inline-flex; align-items: center; gap: 6px; font: inherit; font-weight: 600; font-size: .9rem; padding: 7px 14px; border-radius: var(--radius-sm); border: 1px solid var(--border-strong); background: var(--surface); color: var(--text); cursor: pointer; text-decoration: none; }
.btn:hover { background: var(--surface-2); }
.btn:disabled { opacity: .55; cursor: not-allowed; }
.btn-primary { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
.btn-primary:hover { background: var(--accent); filter: brightness(1.08); }
.btn-danger { color: var(--bad); border-color: var(--bad-border); }
.btn-sm { padding: 3px 9px; font-size: .8rem; }
.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px 16px; }
.field { display: flex; flex-direction: column; gap: 4px; }
.field label, .field .lbl { font-size: .78rem; font-weight: 650; color: var(--text-2); text-transform: uppercase; letter-spacing: .04em; }
.field .hint { font-size: .78rem; color: var(--text-2); }
.field.full { grid-column: 1 / -1; }
input[type="text"], input[type="password"], select { font: inherit; padding: 7px 10px; border: 1px solid var(--border-strong); border-radius: var(--radius-sm); background: var(--surface); color: var(--text); min-width: 0; }
.check-row { display: flex; gap: 10px; align-items: flex-start; padding: 12px; border: 1px solid var(--border); border-radius: var(--radius-sm); background: var(--surface-2); }
.check-row input { margin-top: 3px; width: 18px; height: 18px; }
table { border-collapse: collapse; width: 100%; font-size: .88rem; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--border); vertical-align: top; }
th { font-size: .74rem; text-transform: uppercase; letter-spacing: .04em; color: var(--text-2); background: var(--surface-2); }
.table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--radius); }
dl.kv { display: grid; grid-template-columns: minmax(140px, max-content) 1fr; gap: 6px 16px; margin: 0; }
dl.kv dt { color: var(--text-2); font-weight: 600; }
dl.kv dd { margin: 0; overflow-wrap: anywhere; }
details { border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 8px 12px; margin-top: 12px; }
summary { cursor: pointer; font-weight: 650; }
.progress { height: 12px; border-radius: 999px; background: var(--surface-3); overflow: hidden; margin: 8px 0; }
.progress > span { display: block; height: 100%; background: var(--accent); transition: width .3s; }
.progress.indeterminate > span { width: 30%; }
.log { font-family: var(--mono); font-size: .8rem; background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 8px 10px; max-height: 280px; overflow-y: auto; margin: 0; list-style: none; }
.log li { padding: 1px 0; overflow-wrap: anywhere; }
.log .lv-warn { color: var(--warn); }
.log .lv-error { color: var(--bad); }
.counts { display: flex; flex-wrap: wrap; gap: 8px; margin: 8px 0; }
.count { border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 6px 12px; background: var(--surface-2); min-width: 90px; }
.count .v { font-size: 1.35rem; font-weight: 750; font-variant-numeric: tabular-nums; }
.count .l { font-size: .72rem; text-transform: uppercase; letter-spacing: .05em; color: var(--text-2); font-weight: 650; }
.count.sev-critical .v { color: var(--sev-critical); } .count.sev-high .v { color: var(--sev-high); } .count.sev-medium .v { color: var(--sev-medium); } .count.sev-low .v { color: var(--sev-low); }
.status-banner { border-radius: var(--radius); padding: 16px 20px; border: 1px solid; border-left-width: 8px; margin-bottom: 16px; }
.status-banner .label { font-size: 1.3rem; font-weight: 750; margin: 0 0 4px; }
.st-ok { background: var(--ok-bg); border-color: var(--ok); } .st-ok .label { color: var(--ok); }
.st-warn { background: var(--warn-bg); border-color: var(--warn-border); border-left-color: var(--warn); } .st-warn .label { color: var(--warn); }
.st-bad { background: var(--bad-bg); border-color: var(--bad-border); border-left-color: var(--bad); } .st-bad .label { color: var(--bad); }
.center-msg { max-width: 560px; margin: 60px auto; text-align: center; }
@media (max-width: 860px) {
  .layout { grid-template-columns: 1fr; padding: 16px; }
  .stepper ol { position: static; display: flex; overflow-x: auto; gap: 4px; }
  .stepper li { flex: none; }
  .stepper .lbl-text { display: none; }
  .form-grid { grid-template-columns: 1fr; }
}

/* blast radius: rules in assets/report/blast.css (appended by the build); colors map to UI tokens. */
.br { --attack: var(--bad); --safe: var(--ok); --attack-soft: var(--bad-bg); }
.blast-card { margin-top: 16px; }
/* Receipt code (final step): large, monospaced, easy to read out on a call. */
.receipt-card { text-align: center; border-left: 8px solid var(--accent); }
.receipt-lead { font-size: 1.05rem; font-weight: 700; margin: 0 0 6px; }
.receipt-code { font-family: var(--mono); font-size: clamp(1.4rem, 4.2vw, 2.6rem); font-weight: 750; letter-spacing: .08em; margin: 4px 0 10px; overflow-wrap: anywhere; user-select: all; }
/* blast radius (shared by the report and the local UI; the build appends this file to each host
   stylesheet). Uses only the host tokens plus --attack, --attack-soft and --safe, which each host
   aliases to its own fail / pass tokens. Every selector is scoped under .br. */
.br { --br-text-3: var(--text-3, var(--text-2)); min-width: 0; overflow-wrap: break-word; }
.br button, .br select, .br input { font: inherit; color: inherit; }
.br :focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
.br-top { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 12px 20px; margin-bottom: 18px; }
.br-ask { flex: 1 1 520px; min-width: 0; }
.br-ask label { display: block; color: var(--text-2); font-size: .95rem; margin-bottom: 6px; }
.br-entry { appearance: none; -webkit-appearance: none; background-color: var(--surface); color: var(--text); border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  padding: 8px 40px 8px 12px; font-size: 1.05rem; font-weight: 600; min-height: 44px; max-width: 100%; cursor: pointer;
  background-image: linear-gradient(45deg, transparent 50%, var(--text-2) 50%), linear-gradient(135deg, var(--text-2) 50%, transparent 50%);
  background-position: calc(100% - 20px) 55%, calc(100% - 15px) 55%; background-size: 5px 5px; background-repeat: no-repeat; }
.br-verdict { margin: 14px 0 0; font-size: clamp(1.5rem, 2.6vw, 2.25rem); line-height: 1.15; font-weight: 700; letter-spacing: -.02em; max-width: 30ch; }
.br-verdict .n { font-variant-numeric: tabular-nums; color: var(--attack); }
.br-verdict.is-safe .n { color: var(--safe); }
.br-sub { margin: 6px 0 0; color: var(--text-2); max-width: 70ch; }
.br-scope { margin: 4px 0 0; color: var(--br-text-3); font-size: .9rem; max-width: 80ch; }
.br-switch { display: inline-flex; border: 1px solid var(--border-strong); border-radius: var(--radius-sm); overflow: hidden; background: var(--surface); }
.br-switch button { border: 0; background: none; padding: 8px 16px; min-height: 44px; min-width: 64px; cursor: pointer; color: var(--text-2); }
.br-switch button[aria-pressed="true"] { background: var(--surface-3); color: var(--text); font-weight: 600; }
.br-partial { margin: 0 0 14px; padding: 10px 12px; border-radius: var(--radius-sm); background: var(--attack-soft); color: var(--text); font-size: .9rem; }

.br-main { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 380px); gap: 16px; align-items: start; }
@media (max-width: 1000px) { .br-main { grid-template-columns: minmax(0, 1fr); } .br .br-fix { position: static; } }
.br-panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); min-width: 0; overflow-wrap: break-word; }

/* map */
.br-canvas { position: relative; padding: 8px; }
.br-canvas svg { display: block; width: 100%; height: auto; max-height: 78vh; }
.br-mapnote { margin: 0; padding: 8px 14px 0; color: var(--text-2); font-size: .88rem; }
.br-blast { fill: var(--attack); opacity: .13; transition: r .45s cubic-bezier(.2, .8, .2, 1), opacity .45s ease; }
.br-blast-core { fill: var(--attack); opacity: .12; }
.br-ring { fill: none; stroke: var(--border); stroke-width: 1; }
.br-ring-num { fill: var(--br-text-3); font-size: 11px; font-variant-numeric: tabular-nums; }
.br-sector-line { stroke: var(--border); stroke-width: 1; stroke-dasharray: 2 6; }
.br-sector-name { fill: var(--text-2); font-size: 13px; font-weight: 600; }
.br-edge { fill: none; stroke: var(--border-strong); stroke-width: 1.5; transition: stroke .25s ease, stroke-width .25s ease, opacity .25s ease; }
.br-edge.c-configuration-inferred { stroke-dasharray: 7 5; }
.br-edge.c-correlated { stroke-dasharray: 1.5 4.5; stroke-linecap: round; stroke-width: 2; }
.br-edge.c-operator-declared { stroke-dasharray: 9 4 2 4; }
.br-edge.on-path { stroke: var(--attack); stroke-width: 3.5; }
.br-edge.is-cut { stroke: var(--accent); opacity: .55; }
.br-edge.dim { opacity: .18; }
.br-cut-mark { stroke: var(--accent); stroke-width: 3; stroke-linecap: round; }
.br-node { cursor: pointer; }
.br-node .br-glyph { fill: var(--surface); stroke: var(--text-2); stroke-width: 1.75; transition: fill .25s ease, stroke .25s ease; }
.br-node.reached .br-glyph { stroke: var(--text); }
.br-node.crown .br-glyph { stroke-width: 2.5; stroke: var(--text); }
.br-node.crown.reached .br-glyph { fill: var(--attack-soft); stroke: var(--attack); }
.br-node.crown.safe .br-glyph { stroke: var(--safe); stroke-dasharray: 3 3; fill: var(--surface); }
.br-node.entry .br-glyph { fill: var(--attack); stroke: var(--attack); }
.br-node.unreached { opacity: .38; }
.br-node.crown.safe { opacity: .85; }
.br-node.agg .br-glyph { stroke-dasharray: 2 2; }
.br-agg-n { fill: var(--text); font-size: 9px; font-weight: 700; pointer-events: none; }
.br-lbl { fill: var(--text); font-size: 12.5px; paint-order: stroke; stroke: var(--surface); stroke-width: 4px; stroke-linejoin: round; }
.br-lbl2 { fill: var(--br-text-3); font-size: 11px; paint-order: stroke; stroke: var(--surface); stroke-width: 4px; stroke-linejoin: round; }
.br-node:focus { outline: none; }
.br-node:focus-visible { outline: none; }
.br-node:focus-visible .br-glyph { stroke: var(--focus); stroke-width: 3.5; }
.br-node:focus-visible .br-hit { stroke: var(--focus); stroke-width: 3; fill: none; }
.br-hit { fill: transparent; }
.br-sr { position: absolute !important; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.br-tip { position: absolute; pointer-events: none; background: var(--text); color: var(--surface); padding: 6px 10px; border-radius: var(--radius-sm);
  font-size: 13px; max-width: 280px; opacity: 0; transition: opacity .12s ease; z-index: 5; }
.br-tip.show { opacity: 1; }
.br-legend { display: flex; flex-wrap: wrap; gap: 6px 18px; padding: 10px 14px 12px; border-top: 1px solid var(--border); color: var(--text-2); font-size: 13px; }
.br-legend span { display: inline-flex; align-items: center; gap: 6px; }
.br-legend svg { width: 28px; height: 14px; flex: none; }

/* fix panel */
.br .br-fix { padding: 16px; position: sticky; top: 12px; }
.br-fix h2, .br-path h2, .br-gaps h2 { font-size: 1.1rem; margin: 0 0 4px; }
.br-hint { color: var(--text-2); margin: 0 0 12px; font-size: .92rem; }
.br-meter { height: 10px; border-radius: 5px; background: var(--surface-3); overflow: hidden; margin: 6px 0 4px; }
.br-meter i { display: block; height: 100%; background: var(--attack); border-radius: 5px; transition: width .35s ease; }
.br-meter-lbl { display: flex; justify-content: space-between; gap: 8px; font-size: .88rem; color: var(--text-2); font-variant-numeric: tabular-nums; margin-bottom: 12px; }
.br-fix-item { display: grid; grid-template-columns: 24px 1fr auto; gap: 4px 10px; align-items: start; padding: 10px; min-height: 44px; border: 1px solid var(--border);
  border-radius: var(--radius-sm); margin-bottom: 8px; cursor: pointer; transition: background .2s ease, border-color .2s ease; }
.br-fix-item:hover { border-color: var(--border-strong); }
.br-fix-item:focus-within { outline: 3px solid var(--focus); outline-offset: 2px; }
.br-fix-item input { width: 20px; height: 20px; margin: 2px 0 0; accent-color: var(--accent); cursor: pointer; }
.br-fix-item input:focus-visible { outline: none; }
.br-fix-item .t { font-weight: 600; line-height: 1.3; min-width: 0; overflow-wrap: anywhere; }
.br-fix-item .d { grid-column: 2 / 4; color: var(--text-2); font-size: .86rem; }
.br-fix-item .k { font-variant-numeric: tabular-nums; font-weight: 700; color: var(--attack); white-space: nowrap; }
.br-fix-item.on { background: var(--accent-soft); border-color: var(--accent); }
.br-fix-item.on .k { color: var(--accent); }
.br-fix-item.spent .k { color: var(--br-text-3); font-weight: 500; }
.br-reroute { margin: 10px 0 0; padding: 10px 12px; border-radius: var(--radius-sm); background: var(--attack-soft); color: var(--text); font-size: .9rem; display: none; }
.br-reroute.show { display: block; }
.br .br-reset { background: none; border: 0; color: var(--accent); cursor: pointer; padding: 8px 0; min-height: 44px; text-decoration: underline; }

/* path detail and evidence gaps */
.br-path, .br-gaps { margin-top: 16px; padding: 16px 18px; }
.br-pick { display: flex; flex-wrap: wrap; gap: 8px; margin: 10px 0 14px; }
.br-chip { border: 1px solid var(--border-strong); background: var(--surface); border-radius: 999px; padding: 6px 14px; min-height: 44px; cursor: pointer; }
.br-chip[aria-pressed="true"] { border-color: var(--attack); background: var(--attack-soft); font-weight: 600; }
.br-steps { list-style: none; margin: 0; padding: 0; counter-reset: brs; }
.br-steps li { position: relative; padding: 0 0 16px 40px; counter-increment: brs; }
.br-steps li::before { content: counter(brs); position: absolute; left: 0; top: 0; width: 26px; height: 26px; border-radius: 50%; background: var(--attack);
  color: var(--surface); font-size: 13px; font-weight: 700; display: grid; place-items: center; }
.br-steps li:not(:last-child)::after { content: ""; position: absolute; left: 12px; top: 28px; bottom: 2px; width: 2px; background: var(--attack-soft); }
.br-steps li.br-empty { padding-left: 0; }
.br-steps li.br-empty::before, .br-steps li.br-empty::after { display: none; }
.br .how { font-weight: 600; }
.br .why { color: var(--text-2); font-size: .92rem; }
.br .meta { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px; font-size: .8rem; }
.br-pill { border: 1px solid var(--border); border-radius: 12px; padding: 1px 9px; color: var(--text-2); background: var(--surface-2); max-width: 100%; }
.br-pill.mono { font-family: var(--mono); overflow-wrap: anywhere; }
.br-pill.warn { border-color: var(--attack); color: var(--text); }
.br-pill.fixed { border-color: var(--accent); color: var(--accent); }
.br-steps li.cut::before { background: var(--accent); }
.br-steps li.cut .how { text-decoration: line-through; text-decoration-color: var(--accent); }
.br-empty { color: var(--text-2); padding: 8px 0; }
.br-gaps ul { list-style: none; margin: 0; padding: 0; }
.br-gaps li { padding: 10px 0; border-top: 1px solid var(--border); }
.br-conf { margin: 0 0 10px; color: var(--text-2); font-size: .92rem; }
.br .br-link { background: none; border: 0; padding: 0; color: var(--accent); cursor: pointer; text-decoration: underline; font-weight: 600; text-align: left; min-height: 24px; }

/* list view */
.br-list { padding: 8px 16px 16px; display: none; }
.br-list table { width: 100%; border-collapse: collapse; font-size: .92rem; }
.br-list th, .br-list td { text-align: left; padding: 8px 6px; border-bottom: 1px solid var(--border); vertical-align: top; overflow-wrap: anywhere; }
.br-list th { color: var(--text-2); font-weight: 600; }
.br.view-list .br-list { display: block; }
.br.view-list .br-canvas-wrap { display: none; }
@media (max-width: 640px) {
  .br-list thead { display: none; }
  .br-list tr { display: block; padding: 10px 0; border-bottom: 1px solid var(--border); }
  .br-list td { display: block; border: 0; padding: 2px 0; }
  .br-list td[data-l="Steps"]::before, .br-list td[data-l="How VSAT knows"]::before { content: attr(data-l) ": "; color: var(--text-2); }
  .br-switch { width: 100%; } .br-switch button { flex: 1; }
}
