  function Heap() { this.a = []; }
  Heap.prototype.push = function (v) {
    const a = this.a; a.push(v); let i = a.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (!less(a[i], a[p])) break; const t = a[i]; a[i] = a[p]; a[p] = t; i = p; }
